Example on how to use the JsonSigningVerifier.

             // Additional options to initialize the verifier
             var additionalOptions = VerifierOption.IgnoreOfflineRevocation | VerifierOption.IgnoreRevocationStatusUnknown;

             // Create our json signing verifier
             var verifier = new JsonSigningVerifier(additionalOptions)
             {
                 // Add trusted root's subject public key info sha256 hash
                 // Optional and only required if the root certificate does not exist in the local system's trusted root store
                 TrustedRootCerts = new SubjectPublicKeyInfoHashes { "0727ECF462454A03AF5A9B2728EF8A1291CD386584BB52CF133D280C4D139FAE" },

                 // Create a constraint that checks if the leaf certificate's common name contains "Dell Inc"
                 Constraints = new LeafSubjectCommonNameConstraint("Dell Inc")
             };

             using (var fileLock = new FileLock(@"C:\temp\signed.json", lockNow: true))
             {
                 var result = verifier.Verify(fileLock, out var validatedText, throwExceptions: false);
                 if (result == Win32ErrorCodes.ERROR_SUCCESS)
                 {
                     Console.WriteLine("Json signing validation successful!");
                     Console.WriteLine($"Json payload: {validatedText}");

                     // If necessary perform additional file handling here while file is still locked in scope...
                 }
                 else
                 {
                     Console.WriteLine($"Json signing validation failed with error code: {result}");
                 }
             }

Example on how to use the PeAuthenticodeVerifier.

             // Additional options to initialize the verifier
             var additionalOptions = VerifierOption.IgnoreOfflineRevocation | VerifierOption.IgnoreRevocationStatusUnknown;

             // Create our authenticode verifier
             var verifier = new PeAuthenticodeVerifier(additionalOptions)
             {
                 // Note, TrustedRootCerts at the moment does not work for authenticode validation due to WinVerifyTrust requiring the
                 // root to exist in the local system's trusted root certificate store (hope to get this working in the future)
                 // If you would like to pin to a specific root certificate then you should use Constraints to implement this handling

                 // Create a constraint that checks if the leaf certificate's common name contains "Dell Inc"
                 Constraints = new LeafSubjectCommonNameConstraint("Dell Inc")
             };

             using (var fileLock = new FileLock(@"C:\temp\signed.dll", lockNow: true))
             {
                 var result = verifier.Verify(fileLock, throwExceptions: false);
                 if (result == Win32ErrorCodes.ERROR_SUCCESS)
                 {
                     Console.WriteLine("Authenticode validation successful!");

                     // If necessary perform additional file handling here while file is still locked in scope...
                     // For example, load the assembly here if needed so the file is validated and loaded in the same lock scope
                 }
                 else
                 {
                     Console.WriteLine($"Authenticode validation failed with error code: {result}");
                 }
             }

Example on how to use the SslCertVerifier.

             // Additional options to initialize the verifier
             var additionalOptions = VerifierOption.IgnoreOfflineRevocation | VerifierOption.IgnoreRevocationStatusUnknown;

             // Create our SSL certificate verifier
             var verifier = new SslCertVerifier(additionalOptions)
             {
                 // Add trusted root's subject public key info sha256 hash
                 // Optional and only required if the root certificate does not exist in the local system's trusted root store
                 TrustedRootCerts = new SubjectPublicKeyInfoHashes { "0727ECF462454A03AF5A9B2728EF8A1291CD386584BB52CF133D280C4D139FAE" },

                 // Create a constraint that checks if the leaf certificate's common name contains "Dell Inc"
                 Constraints = new LeafSubjectCommonNameConstraint("*.dell.com")
             };

             var restClient = new RestClient("https://some.service.dell.com/");
             restClient.RemoteCertificateValidationCallback = (RemoteCertificateValidationCallback)verifier.Verify;

             // Now perform execute call to REST api
             // Once we attempt to establish the connection the verifier's Verify method will be called from the callback we set above
             // At that point is where the verifier will validate the SSL/TLS certificate
             restClient.Execute(new RestRequest("api/v1/authorize", Method.GET));


