PeAuthenticodeVerifier signingVerifier = new PeAuthenticodeVerifier();
using (IFileLock fileLock = new FileLock(filename, true /*Lock Now*/))
{
    if (signingVerifier.Verify(fileLock) != Win32ErrorCodes.ERROR_SUCCESS)
        throw new Exception("Failed to validate authenticode signing");

    Assembly.LoadFrom(fileLock.Filepath);
}

