Example of using .

             var algs = new List<string>
             {
                 "PS512",
                 "RS256"
             };

             var signatures = new List<string>();

             // Load our signing certificate that contains the private key for signing
             var signingCert = new X509Certificate2(@"C:\temp\SigningCert.pfx", "", X509KeyStorageFlags.Exportable);

             // Get the bytes we want to sign
             var bytesToSign = Encoding.UTF8.GetBytes("Some data we want signed");

             foreach (var alg in algs)
             {
                 using (var signer = SigningFactory.CreateSigner(alg))
                 {
                     var signatureBytes = singer.Sign(signingCert, bytesToSign);
                     var base64EncodedSignature = Convert.ToBase64String(signatureBytes);
                     signatures.Add(base64EncodedSignature);
                 }
             }

             // Now print out all our signatures
             foreach (var base64EncodedSignature in signatures)
             {
                 Console.WriteLine($"Base64 Encoded Signature: {base64EncodedSignature}");
             }

